subtopics.example:
let x;        // declaration only -> x is undefined
x = 5;        // assignment
const y = 10; // declaration + assignment (required)

{ let a = 1; var b = 2; }
console.log(b); // 2 (var leaks out)
console.log(a); // ReferenceError (let stays in block)

let n = 1; n = 2;     // reassign: OK
// let n = 3;          // redeclare: SyntaxError
const c = 1;
// c = 2;             // reassign const: TypeError

console.log(a); // undefined (var hoisted + initialized)
var a = 1;
console.log(b); // ReferenceError (TDZ)
let b = 2;

const obj = { a: 1 };
obj.a = 2;          // OK — mutating contents
obj.b = 3;          // OK
// obj = {};        // TypeError — reassigning the binding

const total = price * qty; // won't change
let count = 0;             // will be reassigned
// var ... avoid in new code

sandbox.code:
let score = 10;
score = 20; // reassignment allowed
console.log('score:', score); // 20

const MAX = 100;
try {
  MAX = 200; // not allowed
} catch (e) {
  console.log('Error:', e.message);
}

if (true) {
  var leaked = 'I escaped';
  let trapped = 'I stay in the block';
}

console.log(leaked); // works — var is function-scoped
try {
  console.log(trapped);
} catch (e) {
  console.log('Error:', e.message);
}

const user = { name: 'Ada', age: 30 };
user.age = 31;          // OK — mutating a property
user.role = 'admin';    // OK — adding a property
console.log(user);

try {
  user = {};            // reassign the binding
} catch (e) {
  console.log('Error:', e.message);
}

var prices = [10, 20, 30];
var total = 0;
for (var i = 0; i < prices.length; i++) {
  total = total + prices[i];
}
console.log('Total:', total);
// TODO: refactor to const/let appropriately

solution.code:
const prices = [10, 20, 30]; // never reassigned
let total = 0;               // reassigned in the loop
for (let i = 0; i < prices.length; i++) {
  total = total + prices[i];
}
console.log('Total:', total);

brokenCode.code:
console.log(count); // expecting undefined?
let count = 5;
console.log(count);
// ReferenceError: Cannot access 'count' before initialization

solution.code:
let count = 5;
console.log(count); // 5 — read after declaration
count = 6;
console.log(count); // 6

// Buggy with var: logs 3, 3, 3
// Fixed with let:
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 10);
}
// logs 0, 1, 2
